package mz.bam.seeky.android;
import android.app.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;

/** Explicit total, search and pages; selections survive moving between result pages. */
final class RevisionPicker {
    final RevisionNotebook book;final Activity a;final Map<String,RevisionNotebook.Choice> selected=new LinkedHashMap<>();final Set<String> excluded=new HashSet<>(),allKeys=new HashSet<>();
    EditText query;TextView total,previous,next;ListView list;UiDialog dialog;String allQuery;boolean selecting;int page,generation,selectionGeneration;final Handler main=new Handler(Looper.getMainLooper());
    RevisionPicker(RevisionNotebook book){this.book=book;a=book.a;}
    void show(){LinearLayout form=PlusUi.column(a);query=PlusUi.input(a,"Pesquisar notas, cartões e perguntas","",200);total=PlusUi.text(a,"A carregar…",12);form.addView(query);form.addView(total);list=new ListView(a);list.setDivider(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));list.setDividerHeight(PlusUi.dp(a,10));form.addView(list,new LinearLayout.LayoutParams(-1,PlusUi.dp(a,260)));LinearLayout nav=new LinearLayout(a);previous=PlusUi.text(a,"Anterior",14);next=PlusUi.text(a,"Seguinte",14);UiBox.style(previous);UiBox.style(next);nav.addView(previous,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams right=new LinearLayout.LayoutParams(0,-2,1);right.leftMargin=PlusUi.dp(a,10);nav.addView(next,right);form.addView(nav);previous.setOnClickListener(v->{if(page>0){page--;load();}});next.setOnClickListener(v->{page++;load();});query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){page=0;main.removeCallbacks(refresh);main.postDelayed(refresh,220);}});
        dialog=new UiDialog.Builder(a).setTitle("Caderno de revisão").setView(form).setPositiveButton("Preparar PDF",null).setNeutralButton("Seleccionar todos",null).setNegativeButton("Cancelar",null).create();dialog.show();dialog.getButton(-3).setOnClickListener(v->selectAll());dialog.getButton(-1).setOnClickListener(v->prepare());dialog.setOnDismissListener(d->{generation++;selectionGeneration++;main.removeCallbacks(refresh);});load();}
    void selectAll(){if(selecting)return;if(allQuery!=null){allQuery=null;allKeys.clear();excluded.clear();selected.clear();load();return;}final String q=query.getText().toString();final int token=++selectionGeneration;selecting=true;dialog.getButton(-3).setEnabled(false);dialog.getButton(-1).setEnabled(false);PlusUi.longRun(a,()->{Set<String> keys=new HashSet<>();try{book.visit(q,item->keys.add(book.key(item)));PlusUi.post(a,()->{if(token!=selectionGeneration||!dialog.isShowing())return;allQuery=q;allKeys.clear();allKeys.addAll(keys);excluded.clear();load();});}finally{PlusUi.post(a,()->{selecting=false;if(dialog.isShowing()){dialog.getButton(-3).setEnabled(true);dialog.getButton(-1).setEnabled(true);}});}});}
    int selectedCount(){int count=selected.size();for(String key:allKeys)if(!selected.containsKey(key)&&!excluded.contains(key))count++;return count;}
    final Runnable refresh=this::load;
    void load(){final int token=++generation,offset=page*40;final String q=query.getText().toString();PlusUi.run(a,()->{RevisionNotebook.Page result=book.page(q,offset,40);PlusUi.post(a,()->{if(token!=generation||!dialog.isShowing())return;total.setText(Math.min(result.total,offset+1)+"–"+Math.min(result.total,offset+result.rows.size())+" / "+result.total+" · "+selectedCount()+" "+AppLanguage.text(a,"seleccionados"));dialog.getButton(-3).setText(AppLanguage.text(a,allQuery==null?"Seleccionar todos":"Limpar selecção"));previous.setEnabled(page>0);next.setEnabled(offset+result.rows.size()<result.total);list.setAdapter(new BaseAdapter(){public int getCount(){return result.rows.size();}public Object getItem(int p){return result.rows.get(p);}public long getItemId(int p){return p;}public View getView(int at,View recycled,ViewGroup parent){RevisionNotebook.Choice item=result.rows.get(at);CheckBox box=new CheckBox(a);box.setText(AppLanguage.text(a,item.kind)+" · "+AudioTitles.limit(item.title,100,300)+"\n"+item.source);box.setTextColor(AppPalette.of(a).ink);box.setMinHeight(PlusUi.dp(a,64));String key=book.key(item);box.setChecked(selected.containsKey(key)||allKeys.contains(key)&&!excluded.contains(key));box.setOnCheckedChangeListener((b,on)->{if(on){selected.put(key,item);excluded.remove(key);}else{selected.remove(key);if(allQuery!=null)excluded.add(key);}String caption=total.getText().toString();int mark=caption.lastIndexOf(" · ");if(mark>=0)total.setText(caption.substring(0,mark)+" · "+selectedCount()+" "+AppLanguage.text(a,"seleccionados"));});return box;}});});});}
    void prepare(){String all=allQuery;Map<String,RevisionNotebook.Choice> chosen=new LinkedHashMap<>(selected);Set<String> except=new HashSet<>(excluded),keys=new HashSet<>(allKeys);PlusUi.longRun(a,()->{if(all!=null)book.visit(all,item->{String key=book.key(item);if(keys.contains(key)&&!except.contains(key))chosen.put(key,item);});PlusUi.post(a,()->{if(chosen.isEmpty()){PlusUi.toast(a,"Escolha pelo menos um item.");return;}dialog.dismiss();book.prepare(new ArrayList<>(chosen.values()));});});}
}
